// Every Go program starts in package main, at func main.
package main

import "fmt" // the package for printing text

func main() {
	fmt.Println("Hello, world!")
	fmt.Println("Welcome to the Go course.")

	// Println puts spaces between its values and ends the line.
	fmt.Println("Lessons:", 20, "Level:", "basic")
	fmt.Println("2 + 3 =", 2+3)

	// Print adds no newline: \n ends the line.
	fmt.Print("Step ")
	fmt.Print("by step\n")

	// An empty Println writes a blank line.
	fmt.Println()
	fmt.Println("Bye!")
}

package main

import "fmt"

func main() {
	product := "Coffee"
	price := 3.5
	units := 4

	// + joins strings; len counts their bytes.
	label := product + " beans"
	fmt.Println(label, "has", len(label), "characters")

	// Printf fills each verb with a value, in order.
	fmt.Printf("%s costs %.2f euros\n", product, price)
	fmt.Printf("%d units: %.2f euros\n", units, price*float64(units))

	// %v prints any value; %q adds quotes.
	fmt.Printf("%v | %v | %q\n", units, price, product)

	// A width lines up columns: %-8s to the left, %6.2f to the right.
	fmt.Printf("%-8s|%6.2f|\n", "Tea", 2.25)
	fmt.Printf("%-8s|%6.2f|\n", "Cocoa", 12.4)
	fmt.Printf("%-8s|%6d|\n", "Units", units)

	// Sprintf returns the text instead of printing it.
	receipt := fmt.Sprintf("%dx %s = %.2f", units, product, price*float64(units))
	fmt.Println("Receipt:", receipt)
	fmt.Printf("VAT: %d%%\n", 21) // %% writes a percent sign
}

package main

import "fmt"

func main() {
	temperature := 31

	// The condition needs no parentheses, but the braces are required.
	if temperature > 30 {
		fmt.Println("It is hot: drink water")
	} else if temperature > 15 {
		fmt.Println("Nice weather for a walk")
	} else {
		fmt.Println("Take a coat")
	}

	// && (and), || (or) and ! (not) combine conditions.
	age, hasTicket := 17, true
	if age >= 18 && hasTicket {
		fmt.Println("Welcome to the concert")
	} else if hasTicket && !(age < 16) {
		fmt.Println("Welcome, with an adult")
	} else {
		fmt.Println("Sorry, no entry")
	}

	// An init statement runs first; total only exists inside this if.
	price, units := 18.5, 3
	if total := price * float64(units); total >= 50 {
		fmt.Printf("Total %.2f: free shipping\n", total)
	} else {
		fmt.Printf("Total %.2f + 4.95 shipping\n", total)
	}
}

package main

import "fmt"

func main() {
	day := "Saturday"
	// Each case ends on its own: no break needed.
	switch day {
	case "Saturday", "Sunday":
		fmt.Println(day, "is weekend")
	default:
		fmt.Println(day, "is a working day")
	}

	// With no value, switch works like a chain of if / else.
	score := 82
	switch {
	case score >= 90:
		fmt.Println(score, "-> grade A")
	case score >= 80:
		fmt.Println(score, "-> grade B")
	default:
		fmt.Println(score, "-> grade C")
	}

	// An init statement, and fallthrough to run the next case too.
	switch level := 2; level {
	case 2:
		fmt.Println("Level 2: bonus unlocked")
		fallthrough
	case 1:
		fmt.Println("Level 1: basics done")
	}
}

package main

import "fmt"

func main() {
	// Classic form: init; condition; post.
	for i := 1; i <= 5; i++ {
		fmt.Printf("%d x 7 = %d\n", i, i*7)
	}

	// Only a condition: this is Go's "while".
	savings, months := 100.0, 0
	for savings < 150 {
		savings *= 1.10
		months++
	}
	fmt.Printf("%.2f euros after %d months\n", savings, months)

	// No condition at all: it repeats until break.
	n := 0
	for {
		n++
		if n%2 == 0 {
			continue // skip even numbers
		}
		if n*n > 50 {
			break // leave the loop
		}
		fmt.Print(n*n, " ")
	}
	fmt.Println("<- odd squares up to 50")
}

package main

import "fmt"

func main() {
	// An array has a fixed length, and it is part of its type.
	var rainfall [7]float64
	rainfall[0] = 2.5
	rainfall[3] = 11
	rainfall[6] = 4.25
	fmt.Println("Rainfall:", rainfall)

	// [...] lets Go count the elements of the literal.
	days := [...]string{"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
	fmt.Println("Days in a week:", len(days))

	total, wettest := 0.0, 0
	for i := 0; i < len(rainfall); i++ {
		total += rainfall[i]
		if rainfall[i] > rainfall[wettest] {
			wettest = i
		}
	}
	fmt.Printf("Total: %.2f mm\n", total)
	fmt.Println("Wettest day:", days[wettest])

	// Assigning an array copies all of it.
	backup := rainfall
	backup[0] = 99
	fmt.Println("Monday:", rainfall[0], "in the copy:", backup[0])

	// Arrays of the same type can be compared with ==.
	fmt.Println("Same data?", backup == rainfall)
}

package main

import "fmt"

func main() {
	// A slice is a list that can grow: [] without a length.
	playlist := []string{"Intro", "Sunrise", "Rain"}
	fmt.Println(playlist, "len:", len(playlist))

	// append returns the new slice: assign it back.
	playlist = append(playlist, "Harbour", "Night Drive")
	fmt.Println(playlist, "len:", len(playlist))

	// s[from:to] goes from 'from' up to, not including, 'to'.
	fmt.Println("First two:", playlist[:2])
	fmt.Println("From the third:", playlist[2:])
	fmt.Println("Middle:", playlist[1:4])

	// make creates an empty slice with room (cap) for 4.
	ratings := make([]int, 0, 4)
	for i := 1; i <= 6; i++ {
		ratings = append(ratings, i*10)
		fmt.Printf("len=%d cap=%d %v\n", len(ratings), cap(ratings), ratings)
	}

	// A sub-slice shares memory with the original.
	firstTwo := playlist[:2]
	firstTwo[0] = "Overture"
	fmt.Println("Changed through the sub-slice:", playlist[0])
}

package main

import (
	"fmt"
	"sort"
)

func main() {
	// A map links keys to values: map[keyType]valueType.
	stock := map[string]int{"apples": 12, "pears": 5, "plums": 0}
	fmt.Println("Apples:", stock["apples"])

	// Assigning changes a value or adds a new key.
	stock["pears"] = 8
	stock["kiwis"] = 20

	// A missing key gives the zero value; ok says if it exists.
	fmt.Println("Bananas:", stock["bananas"])
	if _, ok := stock["bananas"]; !ok {
		fmt.Println("We do not sell bananas")
	}
	delete(stock, "plums")
	fmt.Println("Kinds of fruit:", len(stock))

	// The order of a map is random: sort the keys first.
	keys := make([]string, 0, len(stock))
	for key := range stock {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for i := 0; i < len(keys); i++ {
		fmt.Printf("%-8s%4d\n", keys[i], stock[keys[i]])
	}
}

package main

import "fmt"

// Parameters go with their types; the result type comes last.
func vat(price float64) float64 { return price * 0.21 }

// A function can return several values.
func share(sweets, children int) (int, int) {
	return sweets / children, sweets % children
}

// Named results start at zero; a bare return sends them back.
func lowHigh(numbers []int) (low, high int) {
	low, high = numbers[0], numbers[0]
	for i := 1; i < len(numbers); i++ {
		if numbers[i] < low {
			low = numbers[i]
		} else if numbers[i] > high {
			high = numbers[i]
		}
	}
	return
}

func main() {
	fmt.Printf("VAT on 40 euros: %.2f\n", vat(40))
	each, left := share(17, 5)
	fmt.Println("Sweets each:", each, "left over:", left)
	_, rest := share(100, 7) // _ ignores a result
	fmt.Println("Left over from 100 among 7:", rest)
	low, high := lowHigh([]int{18, 25, 9, 31, 22})
	fmt.Println("Lowest:", low, "highest:", high)
}

package main

import (
	"errors"
	"fmt"
)

// errors.New creates an error value that can be recognised later.
var ErrNoFunds = errors.New("insufficient funds")

// The error goes last; nil means that everything went well.
func withdraw(balance, amount float64) (float64, error) {
	switch {
	case amount <= 0:
		return balance, fmt.Errorf("invalid amount %.2f", amount)
	case amount > balance:
		return balance, fmt.Errorf("withdraw %.2f: %w", amount, ErrNoFunds) // %w wraps it
	}
	return balance - amount, nil
}

func main() {
	balance, amounts := 100.0, []float64{30, -5, 90, 45}
	for i := 0; i < len(amounts); i++ {
		newBalance, err := withdraw(balance, amounts[i])
		if err != nil {
			fmt.Println("Error:", err)
			fmt.Println("  is ErrNoFunds?", errors.Is(err, ErrNoFunds))
			continue
		}
		balance = newBalance
		fmt.Printf("Took %.2f, balance %.2f\n", amounts[i], balance)
	}
}

package main

import "fmt"

// A struct groups related fields into one type.
type Book struct {
	Title, Author string
	Pages         int
	Read          bool
}

func main() {
	// Fields by name; the missing ones take their zero value.
	novel := Book{Title: "Emma", Author: "Jane Austen", Pages: 474}
	tale := Book{"Matilda", "Roald Dahl", 240, true} // or all, in order

	novel.Read = true // the dot reads and changes fields
	fmt.Println(novel)
	fmt.Printf("%+v\n", tale) // %+v also shows the field names

	// Assigning a struct copies it.
	gift := tale
	gift.Title = "Matilda (gift)"
	fmt.Println(tale.Title, "|", gift.Title)

	// A slice of structs: a small bookshelf.
	shelf := []Book{novel, tale, {Title: "Dracula", Author: "Bram Stoker", Pages: 418}}
	total := 0
	for i := 0; i < len(shelf); i++ {
		fmt.Printf("%-8s %-12s %4d %v\n", shelf[i].Title, shelf[i].Author, shelf[i].Pages, shelf[i].Read)
		total += shelf[i].Pages
	}
	fmt.Println("Total pages:", total)
}

package main

import "fmt"

type Room struct {
	Name          string
	Width, Length float64
}

// A method has a receiver before its name: (r Room).
func (r Room) Area() float64 {
	return r.Width * r.Length
}

// A pointer receiver (*Room) can change the original room.
func (r *Room) Extend(meters float64) {
	r.Length += meters
}

// String() decides how fmt prints a Room.
func (r Room) String() string {
	return fmt.Sprintf("%-8s %.1f x %.1f m", r.Name, r.Width, r.Length)
}

func main() {
	flat := []Room{{"Kitchen", 3, 4.5}, {"Bedroom", 3.5, 4}, {"Bath", 2, 2.5}}
	flat[2].Extend(1) // Go passes &flat[2] for us
	total := 0.0
	for i := 0; i < len(flat); i++ {
		fmt.Printf("%v -> %5.2f m2\n", flat[i], flat[i].Area())
		total += flat[i].Area()
	}
	fmt.Printf("Whole flat: %.2f m2\n", total)
}

package main

import "fmt"

type Player struct {
	Name  string
	Score int
}

// Gets a copy of the number: the change is lost.
func bonusCopy(score int) { score += 50 }

// Gets the address: *score is the original variable.
func bonus(score *int) { *score += 50 }

// With a pointer to a struct, p.Score is enough (no * needed).
func levelUp(p *Player) { p.Score += 100 }

func main() {
	score := 120
	ptr := &score // & gives the address of the variable
	fmt.Println("score:", score, "| *ptr:", *ptr)
	*ptr = 150 // * reaches the value behind the address
	fmt.Println("After *ptr = 150:", score)
	bonusCopy(score)
	fmt.Println("After bonusCopy:", score)
	bonus(&score)
	fmt.Println("After bonus:", score)
	ana := &Player{Name: "Ana", Score: 10}
	levelUp(ana)
	fmt.Println(ana.Name, "now has", ana.Score, "points")
	var nobody *Player // a pointer starts as nil
	fmt.Println("nobody == nil:", nobody == nil)
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	line := "  milk, eggs ,bread,  olive oil  "

	// Split cuts at each comma; TrimSpace removes the spaces around.
	parts := strings.Split(line, ",")
	for i := 0; i < len(parts); i++ {
		parts[i] = strings.TrimSpace(parts[i])
	}
	fmt.Printf("%d items: %q\n", len(parts), parts)
	fmt.Println(strings.Join(parts, " | "))
	fmt.Println("Upper:", strings.ToUpper(parts[0]), "| has eggs:", strings.Contains(line, "eggs"))
	fmt.Println("Replace:", strings.Replace(parts[3], "olive", "sunflower", 1), "| commas:", strings.Count(line, ","))
	fmt.Println(strings.Repeat("-", 24))

	// strconv turns text into numbers and numbers into text.
	units, err := strconv.Atoi("12")
	fmt.Println("12 units x 2 =", units*2, "error:", err)
	price, _ := strconv.ParseFloat("2.75", 64)
	fmt.Println("Price x 2 =", price*2)
	if _, err := strconv.Atoi("twelve"); err != nil {
		fmt.Println("Error:", err)
	}
	label := "Pack of " + strconv.Itoa(units) + ": " + strconv.FormatFloat(price*float64(units), 'f', 2, 64)
	fmt.Println(label)
}

package main

import (
	"fmt"
	"sort"
)

func main() {
	// Over a slice: the index and a copy of each value.
	temps, sum := []float64{18.5, 21, 19.5, 23}, 0.0
	for i, t := range temps {
		fmt.Printf("Day %d: %.1f\n", i+1, t)
		sum += t
	}
	fmt.Printf("Average: %.2f\n", sum/float64(len(temps)))

	// Over a map: key and value, in random order, so sort the keys.
	capitals := map[string]string{"Spain": "Madrid", "Italy": "Rome", "France": "Paris"}
	countries := make([]string, 0, len(capitals))
	for country := range capitals {
		countries = append(countries, country)
	}
	sort.Strings(countries)
	for _, country := range countries {
		fmt.Println(country, "->", capitals[country])
	}

	// Over a string: the byte position and each rune (character).
	city := "Málaga"
	for pos, r := range city {
		fmt.Printf("%d:%c ", pos, r)
	}
	fmt.Println("| bytes:", len(city), "runes:", len([]rune(city)))
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

// check stops the program if something went wrong.
func check(err error) {
	if err != nil {
		fmt.Println("Error:", err)
		os.Exit(1)
	}
}

func main() {
	// WriteFile creates (or replaces) a file in the current folder.
	notes := "Buy bread\nCall the plumber\nWater the plants\n"
	check(os.WriteFile("notes.txt", []byte(notes), 0644))
	// OpenFile with O_APPEND adds lines at the end.
	f, err := os.OpenFile("notes.txt", os.O_APPEND|os.O_WRONLY, 0644)
	check(err)
	fmt.Fprintln(f, "Pay the electricity bill")
	f.Close()
	// Open + bufio.Scanner reads it back line by line.
	file, err := os.Open("notes.txt")
	check(err)
	defer file.Close() // runs when main ends
	scanner := bufio.NewScanner(file)
	for n := 1; scanner.Scan(); n++ {
		fmt.Printf("%d. %s\n", n, scanner.Text())
	}
}

package main

import "fmt"

type Product struct {
	Name  string
	Price float64
	Stock int
}

func (p Product) Value() float64 { return p.Price * float64(p.Stock) }

// Sell lowers the stock, or returns an error if there is not enough.
func (p *Product) Sell(units int) error {
	if units > p.Stock {
		return fmt.Errorf("%s: asked for %d, only %d left", p.Name, units, p.Stock)
	}
	p.Stock -= units
	return nil
}

func main() {
	shop := []Product{{"Notebook", 2.5, 40}, {"Pen", 1.2, 100}, {"Mug", 6.95, 12}, {"Teapot", 18, 3}}
	sales, total := []int{5, 30, 10, 4}, 0.0 // units sold of each product
	for i := range shop {
		if err := shop[i].Sell(sales[i]); err != nil {
			fmt.Println("Error:", err)
		}
		p := shop[i]
		fmt.Printf("%-9s%6.2f%5d%9.2f\n", p.Name, p.Price, p.Stock, p.Value())
		total += p.Value()
	}
	fmt.Printf("Stock value: %.2f\n", total)
}
